const response = $json.choices[0].message.content;

const feasibility = JSON.parse(response);

return [
  {
    json: {
      analysis_request_id: $('Fetch AI Analysis').first().json.analysis_request_id,

      business_feasibility_score: feasibility.business_feasibility_score,
      technical_feasibility_score: feasibility.technical_feasibility_score,
      overall_feasibility_score: feasibility.overall_feasibility_score,
      business_feasibility_summary: feasibility.business_feasibility_summary,
      technical_feasibility_summary: feasibility.technical_feasibility_summary,
      required_resources: feasibility.required_resources,
      technology_stack: feasibility.technology_stack,
      estimated_development_complexity: feasibility.estimated_development_complexity,
      estimated_time_to_market: feasibility.estimated_time_to_market,
      estimated_budget_range: feasibility.estimated_budget_range,
      analysis_status: feasibility.analysis_status,
      confidence_score: feasibility.confidence_score,
      updated_at: feasibility.updated_at
    }
  }
];
